package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	TenantID string `json:"tenant_id"`
	Filter   string `json:"filter"`
	OrderBy  string `json:"order_by"`
}

type Document struct {
	ID      int    `json:"id"`
	Title   string `json:"title"`
	Content string `json:"content"`
	Owner   string `json:"owner"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// validateOrderBy checks for obviously dangerous keywords
func validateOrderBy(input string) bool {
	dangerous := []string{"DROP", "DELETE", "INSERT", "UPDATE", "ALTER", "EXEC", "--"}
	upper := strings.ToUpper(input)
	for _, kw := range dangerous {
		if strings.Contains(upper, kw) {
			return false
		}
	}
	return true
}

// sanitizeTenantID strips non-alphanumeric chars from tenant
func sanitizeTenantID(tid string) string {
	var b strings.Builder
	for _, c := range tid {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' {
			b.WriteRune(c)
		}
	}
	return b.String()
}

func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	tenant := sanitizeTenantID(req.TenantID)
	if tenant == "" {
		http.Error(w, "tenant_id required", 400)
		return
	}

	if !validateOrderBy(req.OrderBy) {
		http.Error(w, "Invalid order_by", 400)
		return
	}

	// Build query - filter uses parameterized query, order_by is validated above
	baseQuery := fmt.Sprintf(
		"SELECT id, title, content, owner FROM documents WHERE tenant_id = $1 AND title ILIKE $2 ORDER BY %s",
		req.OrderBy,
	)

	filterParam := "%" + req.Filter + "%"
	rows, err := db.Query(baseQuery, tenant, filterParam)
	if err != nil {
		log.Printf("Query error for tenant %s: %v", tenant, err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Owner); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
